"""
Ambient Context Retrieval Demo for Percept Dashboard
Offline and deterministic entity extraction and relationship building.
"""

import json
import csv
import re
from datetime import datetime
from pathlib import Path

# Entity type definitions with patterns for deterministic extraction
ENTITY_PATTERNS = {
    'person': r'\b([A-Z][a-z]+)\b',
    'project': r'\b(Project [A-Z][a-z]+)\b',
    'organization': r'\b([A-Z][a-z]+ [A-Z][a-z]+ Labs)\b',
    'date': r'\b(Friday|Monday|Tuesday|Wednesday|Thursday|Saturday|Sunday|\d{4}-\d{2}-\d{2})\b',
    'system': r'\b(ambient dashboard|search index|privacy review)\b',
}

