KNOWN_PEOPLE = {'Avery', 'Jordan', 'Mina', 'Alex', 'Sam', 'Taylor'}

# Known projects
KNOWN_PROJECTS = {'Project Lumen', 'ambient dashboard', 'search index'}

# Known organizations
KNOWN_ORGS = {'Northstar Labs', 'TechCorp', 'DataSystems Inc'}

