    """Extract entities from text using deterministic rules."""
    entities = []

    # Extract people (prioritize known names)
    for person in KNOWN_PEOPLE:
        if person in text:
            entities.append({'name': person, 'type': 'person', 'source_text': text})

    # Extract projects
    for project in KNOWN_PROJECTS:
        if project in text.lower():
            entities.append({'name': project, 'type': 'project', 'source_text': text})

    # Extract organizations
    for org in KNOWN_ORGS:
        if org in text:
            entities.append({'name': org, 'type': 'organization', 'source_text': text})

    # Extract dates (day names)
    for date in ENTITY_PATTERNS['date'].findall(text):
        if date not in [e['name'] for e in entities]:
            entities.append({'name': date, 'type': 'date', 'source_text': text})

