    people = sorted(set(e['name'] for e in entities if e['type'] == 'person'))
    projects = sorted(set(e['name'] for e in entities if e['type'] == 'project'))
    orgs = sorted(set(e['name'] for e in entities if e['type'] == 'organization'))
    dates = sorted(set(e['name'] for e in entities if e['type'] == 'date'))

    summary = f"""=== Ambient Context Summary ===

Conversations Analyzed: {len(conversations)}
Time Range: {conversations[0]['timestamp']} to {conversations[-1]['timestamp']}

--- Extracted Entities ---
People ({len(people)}): {', '.join(people)}
Projects ({len(projects)}): {', '.join(projects)}
Organizations ({len(orgs)}): {', '.join(orgs)}
Dates ({len(dates)}): {', '.join(dates)}

--- Relationships ---
Total Relationships: {len(relationships)}
"""

