    summary = generate_summary(conversations, all_entities, relationships)
    with open(summary_path, 'w') as f:
        f.write(summary)
    print(f"Summary saved to: {summary_path}")

    # Create and save context packet
    context_packet = create_context_packet(conversations, all_entities, relationships)
    with open(context_path, 'w') as f:
        json.dump(context_packet, f, indent=2)
    print(f"Context packet saved to: {context_path}")

    # Export entities to CSV
    export_entities_csv(all_entities, entities_path)
    print(f"Entities exported to: {entities_path}")

    print("\n=== Demo Complete ===")
    print("\nGenerated files:")
    print(f"  - {summary_path} (human-readable summary)")
    print(f"  - {context_path} (machine-readable JSON)")
    print(f"  - {entities_path} (CSV entity list)")

if __name__ == '__main__':
    main()
